// Rum Island is a physical home port: beach <-- tavern --> selected voyage.
let homeActive=false,homeNPCs=[],activeEncounter=null,beachWasEntered=false,beachCooldown=0;
const voyages={5:{name:'The Docks',brief:'Release the harbor winch, climb the customs roof, rescue the provisioner and defeat the blockade captain.',reward:'Provision stall · first PDF scrap'},6:{name:'Goblin Canopy',brief:'Climb the root tower, open Gary’s cage, and take the high rope route to the goblin lookout.',reward:'Gary’s repair bench · second PDF scrap'},7:{name:'The Hollow Tide',brief:'Light two shrine braziers, recover the PDF from the upper sanctuary and free Mr. Fluffy.',reward:'Dragon roost · third PDF scrap'},8:{name:'Ruins of Bad Decisions',brief:'Raise the ruined bridge, find the salvage merchant in the watchtower and collect Captain Hangover’s tab.',reward:'Salvage stall · final PDF scrap'},9:{name:'Trial of Clippy',brief:'Four scraps. Three repairs. One ancient PDF. Settle the paperwork.',reward:'Final encounter'}};
function selectedVoyage(){return voyages[save.missionSelected]?save.missionSelected:null;}
function voyageLocked(id){return id===9&&(save.scraps.length<4||save.repairs.length<3);}
function closeHomePanel(){mode='visit';$('#overlay').hidden=true;$('#hud').hidden=false;$('#controls').hidden=false;homeHUD();}
function enterHome(){start(4);homeActive=true;mode='visit';chapters[4].length=3000;objects=[];actors=[];covers=[];ladders=[{x:1250,y:185,h:267}];solids=[{x:0,y:FLOOR,w:3000,h:110,kind:'wood'},{x:1180,y:185,w:430,h:17,kind:'wood'}];player.x=1550;player.y=366;player.cloak=0;camera=player.x-330;cameraY=0;chosenQuest=save.missionSelected||5;homeNPCs=[];const roles=[['Gary the Goblin',0,1460,'Repair bench'],['Farmer’s Market Lady One',1,1850,'Provisions'],['Farmer’s Market Lady Two',2,2160,'Salvage']];for(const [name,row,x,role]of roles)if(save.crew.includes(name))homeNPCs.push({name,row,x,role});beachWasEntered=false;beachCooldown=0;activeEncounter=null;talk(selected==='nova'?'Nova':'Sylvanas','Beach to the left. Missions on the computer. Departure through the right door. Try to leave the building standing.',5);homeHUD();}
hub=enterHome;window.RumIsland.hub=enterHome;
function missionComputer(){const id=chosenQuest||save.missionSelected||5;const q=voyages[id];panel(`<div class="computer-head"><p class="eyebrow">Tavern mission computer</p><h2>Select your next voyage</h2><p>Choose a destination here. Walk out the <b>right-hand door</b> to depart.</p></div><div class="computer-layout"><nav class="computer-list">${Object.entries(voyages).map(([n,v])=>`<button data-destination="${n}" class="${+n===id?'selected':''}" ${voyageLocked(+n)?'disabled':''}><span>${save.quests.includes(+n)?'✓':+n===9?'✦':'⚓'}</span><b>${v.name}</b><small>${voyageLocked(+n)?'Needs 4 scraps & 3 repairs':save.quests.includes(+n)?'Completed · replay':'Available'}</small></button>`).join('')}</nav><article class="computer-detail"><img src="assets/${id===6||id===7?'forest-panorama':'facility-panorama'}.webp" alt="Voyage destination"><h3>${q.name}</h3><p>${q.brief}</p><p class="mission-reward">${q.reward}</p><button id="select-mission" class="primary" ${voyageLocked(id)?'disabled':''}>${save.missionSelected===id?'Destination selected ✓':'Select this destination'}</button><p class="fine">Current destination: ${selectedVoyage()?.name||'None selected'}</p></article></div><footer class="computer-footer"><button id="computer-back" class="secondary">Back to tavern</button><button id="computer-switch" class="secondary">Switch to ${selected==='nova'?'Sylvanas':'Nova'}</button></footer>`);document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{chosenQuest=+b.dataset.destination;missionComputer();});$('#select-mission').onclick=()=>{if(voyageLocked(chosenQuest))return;save.missionSelected=chosenQuest;persist();closeHomePanel();talk('Mission computer',voyages[chosenQuest].name+' selected. Leave through the right-hand door when ready.',4);};$('#computer-back').onclick=closeHomePanel;$('#computer-switch').onclick=()=>{selected=selected==='nova'?'sylvanas':'nova';save.character=selected;persist();missionComputer();};}
tavernBoard=missionComputer;
function repairBench(){panel(`<p class="eyebrow">Gary’s repair bench · ${save.coins} doubloons</p><h2>Put the goblin to work</h2><p>“Structural integrity is a suggestion, Captain. Payment isn’t.”</p><div class="home-services">${['Roof & lanterns','Bar & furniture','Dock & crew berths'].map((name,i)=>`<button data-build="${i}" ${save.repairs.includes(i)||save.coins<20?'disabled':''}><b>${name}</b><small>${save.repairs.includes(i)?'✓ Built':'20 doubloons · visible tavern improvement'}</small></button>`).join('')}</div><button id="service-back" class="secondary">Back to tavern</button>`);document.querySelectorAll('[data-build]').forEach(b=>b.onclick=()=>{const i=+b.dataset.build;if(save.coins<20||save.repairs.includes(i))return;save.coins-=20;save.repairs.push(i);persist();effect('punch');repairBench();});$('#service-back').onclick=closeHomePanel;}
function residentService(n){if(n.row===0){repairBench();return;}const provisioning=n.row===1;panel(`<p class="eyebrow">${n.role} · ${save.coins} doubloons</p><h2>${n.name}</h2><p>${provisioning?'“You can’t fight skeletons on an empty stomach. Well, they can. You can’t.”':'“Bring me pirate scrap. I’ll turn questionable debris into useful equipment.”'}</p><p>${provisioning?'Buy provisions for +1 maximum health on your next voyage.':'Buy a tuned weapon for 20% more weapon damage on your next voyage.'}</p><button id="buy-service" class="primary" ${save.coins<5||save[provisioning?'provisioned':'weaponTuned']?'disabled':''}>${save[provisioning?'provisioned':'weaponTuned']?'Ready for next voyage ✓':'Prepare next voyage · 5 doubloons'}</button><button id="service-back" class="secondary">Back to tavern</button>`);$('#buy-service').onclick=()=>{if(save.coins<5||save[provisioning?'provisioned':'weaponTuned'])return;save.coins-=5;save[provisioning?'provisioned':'weaponTuned']=true;persist();residentService(n);};$('#service-back').onclick=closeHomePanel;}
const beachEncounters=[
 ['chat','Extra Military Instruction','Chat has installed the RAID array in a coffee maker again. The inspection is going poorly.',['Assign remedial cable counting','Let Pickles inspect it'],['Chat counts to seven, loses the count, and requests a transfer.','Pickles eats the evidence. The inspection passes.']],
 ['marine','Timeshare deployment','A Space Marine has arrived carrying a tankard and a brochure labeled Eternal Crusade Getaway.',['Ask about the mandatory briefing','Offer him a bar stool'],['The briefing lasts eight hundred years. Sylvanas leaves after slide two.','The bar stool survives. The floor files a complaint.']],
 ['hoa','HOA inspection','The HOA ladies demand a permit for the volcano. They have measured the lava.',['Show Admiral Bunny’s warrant','Charge an inspection fee'],['The decorative warrant is accepted. Nobody admits they can’t read it.','They invoice you for invoicing them. Gary invoices everybody.']],
 ['crowbar','The crowbar incident','A crowbar stands upright in the sand. Beside it: a note reading “I was told this was a stealth mission.”',['Test the scientific method','Recruit it as management'],['Nova hits the crate. Peer review is explosive.','The crowbar immediately improves staff morale by saying nothing.']],
 ['chat','RAID array funeral','Chat is assembling a tiny Viking longship for the server rack. Somebody has brought inappropriate kindling.',['Cancel the funeral','Conduct a readiness inspection'],['Chat receives one last chance. Pickles is already chewing the chance.','The ship passes flotation. The server does not.']],
 ['marine','Leg day','An Ultramarine asks whether the beach has a regulation squat rack.',['Point at the palm tree','Ask Gary to build one'],['The tree is now regulation height. The coconuts are terrified.','Gary quotes the Imperial treasury. The Marine calls it reasonable.']],
 ['hoa','Dragon zoning','The HOA says Mr. Fluffy violates the two-pet limit. He is one undead dragon.',['Request their arithmetic','Summon the dragon'],['They count wings as residents. Jenny rejects the methodology.','Mr. Fluffy smiles. The HOA approves a dragon-sized exception.']],
 ['crowbar','Mandatory stealth equipment','A sealed crate marked QUIET ENTRY contains only a crowbar and three bells.',['Open it quietly','Let Nova sign the receipt'],['The bells ring. Somewhere, a guard gains overtime.','Nova signs “plausible deniability” and keeps the crowbar.']],
 ['chat','Password rotation','Chat rotates a keyboard physically and declares the security audit complete.',['Request another quarter turn','Ask Jenny for a review'],['The password is now upside down. Security improves geometrically.','Jenny: “Confidence: extraordinary. Competence: insufficient.”']],
 ['marine','Career regret','A Guardsman has been assigned to count grains of sand before deployment.',['Give him a clipboard','Call it reconnaissance'],['He salutes. He has never been so prepared to regret a career.','The beach is declared hostile. Sand gets into his boots anyway.']],
 ['hoa','Noise ordinance','The HOA objects to Nova’s rifle, Sylvanas’s curses, and Gary’s hammer.',['Offer designated quiet hours','Ask them to inspect the bar fight'],['Quiet hours are scheduled during the volcano eruption.','They issue the skeletons a written warning. It is immediately eaten.']],
 ['crowbar','A very qualified applicant','The crowbar submits a résumé: opening doors, closing arguments, management experience.',['Hire for doors','Hire for negotiations'],['The doors agree to remain open.','All negotiations become remarkably brief.']],
 ['chat','Cable accountability','Chat insists there were twelve cables. Pickles insists there were twelve snacks.',['Count the empty sockets','Promote Pickles'],['Both counts are correct. The network is entirely theoretical.','Pickles receives a decorative warrant and eats it.']],
 ['marine','Tech support cult','A red-robed technician blesses the rum dispenser with incense.',['Ask for a reboot','Offer the sacred idiot scroll'],['The machine dispenses rum and a firmware update.','“Skynet, but Catholic with incense.” The technician takes notes.']],
 ['hoa','Pirate parking','The HOA disputes the ship’s parking permit. It is anchored offshore.',['Have a wonderful day','Request the wrath permit'],['“You don’t want to suffer my wrath!” The beach applauds politely.','The permit has expired. Sylvanas revokes the wrath.']],
 ['crowbar','Crate of destiny','The crowbar is guarding a crate that contains another, smaller crate.',['Keep opening crates','Ask Samus to assess'],['The final crate contains a bill for storage.','“Trap.” She pockets the crowbar anyway.']],
 ['chat','Field day','Chat has polished a palm tree and labeled the surf “unserviceable.”',['Inspect the tree','Authorize surf repairs'],['The tree fails for fingerprints. Chat requests leave.','Chat submits a work order to the moon. The tide ignores it.']],
 ['marine','No touchy','The Emperor’s Secret Service has cordoned off one suspicious coconut.',['Respect the perimeter','Offer a coconut warrant'],['The coconut remains secure. The rum remains unsecured.','Admiral Bunny’s paperwork defeats eight thousand years of procedure.']],
 ['hoa','Hat permit','The HOA asks why Ami’s witch hat contains an entire forest.',['Declare a nature preserve','Offer a mushroom census'],['The owl becomes the zoning commissioner.','The mushrooms refuse to stand still for the count.']],
 ['crowbar','Portal maintenance','A crowbar has appeared beside a flickering purple portal.',['Apply percussive maintenance','Let Sylvanas handle it'],['The portal stops flickering. It now hums angrily.','“Some of us possess qualifications.” The crowbar sulks.']],
 ['chat','Under the stairs','Chat has stacked supplies under the stairs and then become trapped behind them.',['Issue a tactical extraction','Ask Gary for assistance'],['Samus extracts Chat, two buckets, and an inexplicable printer.','Gary charges by the swear word. Business is excellent.']],
 ['marine','Happy fire noises','A green-armored Marine offers to toast marshmallows with his flamethrower.',['Accept one marshmallow','Provide a bucket'],['The marshmallow is glorious. The stick has joined the atmosphere.','He labels it “small fire containment system” and salutes.']],
 ['hoa','Tavern standards','The HOA wishes to outlaw bad decisions at Rum Island.',['Read the establishment’s name','Ask for an appeal'],['They discover the branding problem and retreat.','The appeal is heard by the crowbar. Motion denied.']],
 ['crowbar','Ancient PDF opener','The crowbar claims it can open the Ancient PDF without software.',['Test that theory','Refer it to Clippy'],['The document remains closed. The computer case does not.','Clippy detects a competing office assistant and panics.']]
];
function chooseBeachEncounter(){const recent=save.beachRecent||[];const pool=beachEncounters.map((e,i)=>i).filter(i=>!recent.includes(i));const id=pool[Math.floor(Math.random()*pool.length)];activeEncounter={id,data:beachEncounters[id],resolved:false};save.beachRecent=[...recent,id].slice(-8);persist();beachCooldown=35;}
function beachInteraction(){if(!activeEncounter)chooseBeachEncounter();const e=activeEncounter.data;panel(`<p class="eyebrow">Rum Island beach · questionable company</p><h2>${e[1]}</h2><p>${e[2]}</p><div class="encounter-choices">${e[3].map((c,i)=>`<button data-beach-choice="${i}" class="secondary">${c}</button>`).join('')}</div><button id="beach-back" class="secondary">Walk away</button>`);document.querySelectorAll('[data-beach-choice]').forEach(b=>b.onclick=()=>{const i=+b.dataset.beachChoice;if(!activeEncounter.resolved){save.coins+=2;activeEncounter.resolved=true;persist();}panel(`<p class="eyebrow">Incident report</p><h2>${e[1]}</h2><p>${e[4][i]}</p><p class="fine">Encounter resolved · 2 doubloons</p><button id="beach-back" class="primary">Back to the beach</button>`);$('#beach-back').onclick=closeHomePanel;});$('#beach-back').onclick=closeHomePanel;}
function nearHome(){if(player.x<850&&activeEncounter&&Math.abs(player.x-500)<180)return{type:'beach',label:'Investigate '+activeEncounter.data[1]};if(Math.abs(player.x-2500)<100)return{type:'computer',label:'Use mission computer'};if(player.x>2790)return{type:'door',label:selectedVoyage()?'Depart for '+selectedVoyage().name:'Choose a mission on the computer first'};const n=homeNPCs.find(n=>Math.abs(player.x-n.x)<95);if(n)return{type:'resident',n,label:'Talk to '+n.name+' · '+n.role};if(save.crew.includes('Mr. Fluffy')&&Math.abs(player.x-1190)<80&&player.y<300)return{type:'dragon',label:'Greet Mr. Fluffy'};return null;}
function homeInteract(){const near=nearHome();if(!near)return;if(near.type==='computer')missionComputer();else if(near.type==='resident')residentService(near.n);else if(near.type==='beach')beachInteraction();else if(near.type==='dragon'){player.energy=100;talk('Mr. Fluffy','[Affectionate undead-dragon rumbling.] Energy restored. The rafters are nervous.',4);}else if(near.type==='door'){const id=save.missionSelected;if(!id||voyageLocked(id)){talk('Nova','Computer first, Captain. Pick where we’re going.',3);return;}start(id);}}
function homeHUD(){hud();$('#chapter').textContent=player.x<1000?'The beach':'Rum Island Tavern';$('#objective').textContent=selectedVoyage()?'Destination: '+selectedVoyage().name+' · exit right':'Computer → choose mission · door → depart';const near=nearHome();$('#hint').textContent=near?'E · '+near.label:'← Beach & random encounters · Computer & departure →';}
function homeStep(dt){clock+=dt;music(dt);fireCd=Math.max(0,fireCd-dt);player.attack=Math.max(0,player.attack-dt);if(timeTalk>0){timeTalk-=dt;if(timeTalk<=0)$('#dialogue').hidden=true;}const l=ladders.find(l=>Math.abs(l.x-player.x-17)<30&&player.y+86>=l.y-3&&player.y+86<=l.y+l.h+3);if((keys.up||keys.down)&&l){player.vy=0;player.climb=true;player.x=l.x-17;player.y+=((keys.down?1:0)-(keys.up?1:0))*135*dt;if(player.y+86<=l.y){player.y=l.y-86;player.climb=false;player.ground=true;}if(player.y+86>=l.y+l.h){player.y=l.y+l.h-86;player.climb=false;player.ground=true;}}if(press.jump&&player.ground){player.climb=false;player.ground=false;player.vy=-520;}player.vx=((keys.right?1:0)-(keys.left?1:0))*185;if(player.vx){player.face=Math.sign(player.vx);player.climb=false;}player.x=Math.max(30,Math.min(2935,player.x+player.vx*dt));if(!player.climb){const previous=player.y;player.vy+=1350*dt;player.y+=player.vy*dt;player.ground=false;for(const s of solids)if(player.x+34>s.x&&player.x<s.x+s.w&&previous+86<=s.y+3&&player.y+86>=s.y&&player.vy>=0){player.y=s.y-86;player.vy=0;player.ground=true;}}if(keys.attack&&fireCd===0){player.attack=.4;fireCd=.45;effect('punch');}camera=Math.max(0,Math.min(2040,player.x-330));cameraY=0;companionStep(dt);if(player.x<850&&!beachWasEntered){chooseBeachEncounter();beachWasEntered=true;}if(player.x>1000)beachWasEntered=false;beachCooldown-=dt;if(player.x<850&&beachCooldown<=0)chooseBeachEncounter();if(player.x>=2880){if(selectedVoyage()&&!voyageLocked(save.missionSelected)){homeInteract();return;}player.x=2820;}if(press.interact)homeInteract();if(!homeActive)return;for(const k in press)delete press[k];homeHUD();}
function atlasFrame(key,row,f,x,bottom,h){const im=assets[key];if(!im)return;const m=typeof SPRITE_BOUNDS!=='undefined'?SPRITE_BOUNDS[key]:null,c=m?.frames[row*4+f];if(c){const hh=h*c.h/m.base,ww=h*c.w/m.base;ctx.drawImage(im,c.x,c.y,c.w,c.h,x-camera-ww/2,bottom-hh,ww,hh);}else{const rows=key==='residents'?3:1;ctx.drawImage(im,f*im.width/4,row*im.height/rows,im.width/4,im.height/rows,x-camera-h*.4,bottom-h,h*.8,h);}}
function renderHome(){ctx.setTransform(1,0,0,1,0,0);ctx.imageSmoothingEnabled=false;rect(0,0,VW,VH,'#101c27');if(assets.homeContinuous){ctx.drawImage(assets.homeContinuous,-camera,0,3000,VH);}else if(assets.home){const im=assets.home,hh=im.height/2;ctx.drawImage(im,0,0,im.width,hh,-camera,0,1050,VH);ctx.drawImage(im,0,hh,im.width,hh,1050-camera,0,1950,VH);}else bg();for(const s of solids)if(s.h<25){rect(s.x-camera,s.y,s.w,8,'#705438');rect(s.x-camera,s.y,s.w,2,'#b89564');for(let x=s.x;x<s.x+s.w;x+=38)path([[x-camera,s.y+3],[x-camera,s.y+8]],'#392b24',1);}for(const l of ladders){path([[l.x-camera-12,l.y],[l.x-camera-12,FLOOR]],'#9f805b',3);path([[l.x-camera+12,l.y],[l.x-camera+12,FLOOR]],'#9f805b',3);for(let y=l.y;y<FLOOR;y+=17)rect(l.x-camera-12,y,24,3,'#c9ab77');}
 // Resident furniture adds services to the actual tavern.
 for(const n of homeNPCs)atlasFrame('residents',n.row,Math.floor(clock*3+n.row)%4,n.x,FLOOR,n.row===0?65:82);
 if(save.crew.includes('Mr. Fluffy'))sprite({x:1160,y:85,w:35,h:100,face:1},'resident',3);
 if(save.repairs.includes(0))for(let x=1120;x<2900;x+=230){path([[x-camera,78],[x-camera,110]],'#675039',2);rect(x-camera-7,110,14,20,'#6b4e30');rect(x-camera-4,113,8,13,'#f5c36b');rect(x-camera-9,108,18,3,'#927145');ctx.fillStyle='#ffd17a18';ctx.beginPath();ctx.arc(x-camera,122,35,0,7);ctx.fill();}
 if(save.repairs.includes(1)){const x=1660-camera;rect(x-60,410,120,8,'#b89461');rect(x-50,418,7,34,'#6b4d32');rect(x+43,418,7,34,'#6b4d32');for(let i=0;i<4;i++){rect(x-40+i*22,397,9,13,'#486c59');rect(x-39+i*22,393,6,4,'#c0aa7c');}}
 if(save.repairs.includes(2)){const x=2710-camera;rect(x-55,419,110,8,'#a39170');for(const d of [-50,45])rect(x+d,427,5,25,'#71583e');rect(x-50,414,28,5,'#d4c0a0');}
 const x=2500-camera;ctx.save();ctx.globalAlpha=.2+.08*Math.sin(clock*3);ctx.strokeStyle='#89e3e6';ctx.lineWidth=3;ctx.strokeRect(x-57,288,114,70);ctx.restore();rect(x+44,290,5,5,selectedVoyage()?'#9ceaac':'#e9c27a');const dx=2870-camera;ctx.save();ctx.globalAlpha=selectedVoyage()?.5:.15;ctx.strokeStyle=selectedVoyage()?'#f6d398':'#a3afb8';ctx.lineWidth=3;ctx.strokeRect(dx-35,195,80,257);ctx.restore();
 if(activeEncounter){const f={chat:0,marine:1,hoa:2,crowbar:3}[activeEncounter.data[0]];atlasFrame('beachGuests',0,f,500,FLOOR+Math.sin(clock*2)*2,f===1?115:90);}
 const near=nearHome();if(near){ctx.strokeStyle='#f2d298';ctx.lineWidth=2;ctx.beginPath();ctx.arc(player.x-camera+17,player.y-12,7,0,Math.PI*2);ctx.stroke();}if(partner)sprite(partner,selected==='nova'?'sylvanas':'nova');sprite(player,selected);}
const homeOriginalStart=start;start=function(n){homeActive=false;if(n===4)chapters[4].length=1500;homeOriginalStart(n);if(n>=5){if(save.provisioned){player.hp=7;player.maxHp=7;save.provisioned=false;}if(save.weaponTuned){player.weaponMultiplier=1.2;save.weaponTuned=false;}persist();}};window.RumIsland.start=start;window.RumIsland.homeInteract=homeInteract;window.RumIsland.homeStep=homeStep;window.RumIsland.computer=missionComputer;
